import { useState, useEffect } from "react";
import api from "../../servicios/api";
import {
  crearEvaluacionPsico,
  actualizarEvaluacionPsico,
} from "../../servicios/evaluacionPsico";

// SUBDIMENSIÓN III: MOTRICIDAD Y CUIDADO DE SÍ MISMO
const ITEMS_MOTRICIDAD = [
  { id: 101, descripcion: "Se desplaza con coordinación y equilibrio." },
  { id: 102, descripcion: "Combina diferentes movimientos y posturas al desplazarse." },
  { id: 103, descripcion: "Corre con fluidez, variando velocidad, dirección y tipo de desplazamiento." },
  { id: 104, descripcion: "Mantiene la coordinación y control dinámico de su cuerpo en actividades motrices." },
  { id: 105, descripcion: "Ejecuta movimientos de manipulación que requieren control muscular fino." },
  { id: 106, descripcion: "Efectúa trabajos grafo-motores con precisión y seguridad." },
  { id: 107, descripcion: "Manipula objetos y herramientas con precisión." },
  { id: 108, descripcion: "Realiza ejercicios que requieren esfuerzo físico sostenido." },
  { id: 109, descripcion: "Realiza prácticas de autocuidado e higiene corporal en forma autónoma." },
  { id: 110, descripcion: "Cuida y guarda sus pertenencias (TDA)." },
  { id: 111, descripcion: "Manifiesta iniciativa en su cuidado y bienestar personal (TDA)." },
  { id: 112, descripcion: "Identifica situaciones u objetos riesgosos para su seguridad (TDA)." },
  { id: 113, descripcion: "Presenta automatismos o movimientos estereotipados (balanceo, manos, etc.)." },
];

// Escala del PDF
const ITEMS_COMUNICATIVAS = [
  { id: 1, descripcion: "Se comunica e interactúa con los demás de manera espontánea." },
  { id: 2, descripcion: "Se comunica e interactúa con los demás de manera guiada." },
  { id: 3, descripcion: "Participa en conversaciones con sus pares y/o adultos de forma espontánea." },
  { id: 4, descripcion: "La pronunciación, orden y estructura gramatical favorecen la comprensión del mensaje." },
  { id: 5, descripcion: "Utiliza oraciones completas en intervenciones orales/en lengua de señas." },
  { id: 6, descripcion: "Relata en forma secuenciada y clara experiencias personales." },
  { id: 7, descripcion: "Realiza y cumple instrucciones entregadas oralmente/en lengua de señas." },
  { id: 8, descripcion: "Ajusta su lenguaje a diversos contextos e interlocutores." },
  { id: 9, descripcion: "Su expresión oral/señada es coherente con su expresión facial/corporal." },
  { id: 10, descripcion: "Utiliza palabras, señas o conceptos especializados/rebuscados cuando corresponde." },
  { id: 11, descripcion: "Modula volumen y claridad de la voz/señalización según la situación." },
  { id: 12, descripcion: "Conoce y usa un vocabulario amplio." },
  { id: 13, descripcion: "Comunica sensaciones, emociones, necesidades e ideas a través del lenguaje." },
  { id: 14, descripcion: "Repite con frecuencia palabras/señas u oraciones (ecolalia)." },
];
// SUBDIMENSIÓN IV: HÁBITOS DE APRENDIZAJE
const ITEMS_APRENDIZAJE = [
  { id: 1, descripcion: "Muestra preferencias e intereses diversos" },
  { id: 2, descripcion: "Se muestra activo e interesado por su entorno" },
  { id: 3, descripcion: "Se concentra en las actividades y acciones de la clase" },
  { id: 4, descripcion: "Mantiene atención sostenida al trabajar solo" },
  { id: 5, descripcion: "Mantiene atención sostenida al trabajar con otros" },
  { id: 6, descripcion: "Persiste en los trabajos y tareas hasta concluirlos" },
  { id: 7, descripcion: "Concluye los trabajos de forma ordenada. Es sistemático en la realización de su trabajo" },
  { id: 8, descripcion: "A partir de las instrucciones desarrolla su trabajo de manera autónoma" },
  { id: 9, descripcion: "Prefiere trabajar solo/a" },
  { id: 10, descripcion: "Trabaja mejor en colaboración con otros/as" },
  { id: 11, descripcion: "Le gusta resolver problemas" },
  { id: 12, descripcion: "Emprende con entusiasmo tareas nuevas" },
  { id: 13, descripcion: "Le gusta la experimentación" },
  { id: 14, descripcion: "Es competitivo/a" },
  { id: 15, descripcion: "Es creativo/a" },
];

// SUBDIMENSIÓN VI: CAPACIDADES SENSOPERCEPTIVAS
const ITEMS_SENSOPERCEPTIVAS = [
  { id: 301, descripcion: "Responde cuando se le habla con volumen de voz natural." },
  { id: 302, descripcion: "Repite las rimas, canciones, refranes, dichos que se le enseñan." },
  { id: 303, descripcion: "Responde a mensajes orales simples." },
  { id: 304, descripcion: "Identifica y localiza la fuente de sonido en el medio ambiente." },
  { id: 305, descripcion: "En conversaciones grupales espontáneas, mira o atiende hacia la persona que habla." },
  { id: 306, descripcion: "Se expresa a través de actividades musicales." },
  { id: 307, descripcion: "Se expresa a través de actividades plásticas." },
  { id: 308, descripcion: "Para leer o escribir necesita acercarse a textos o pizarrón (uso de vista)." },
  { id: 309, descripcion: "Se desplaza evitando obstáculos presentes en el trayecto." },
  { id: 310, descripcion: "Distingue imágenes, textos y colores." },
  { id: 311, descripcion: "Responde a gestos o señas comunicativas de otros." },
];
// SUBDIMENSIÓN VII: LECTURA Y ESCRITURA
const ITEMS_LECTURA_ESCRITURA = [
  { id: 601, descripcion: "Reconoce y diferencia diferentes tipos de textos." },
  { id: 602, descripcion: "Describe lugares, hechos, personas o personajes de textos leídos." },
  { id: 603, descripcion: "Extrae información de los textos leídos." },
  { id: 604, descripcion: "Expresa su opinión sobre los textos leídos." },
  { id: 605, descripcion: "Lee diversos tipos de textos sugeridos." },
  { id: 606, descripcion: "Reconoce la correspondencia entre los sonidos y las letras." },
  { id: 607, descripcion: "Identifica palabras a primera vista por sus características gráficas." },
  { id: 608, descripcion: "Identifica y reconoce las letras del alfabeto." },
  { id: 609, descripcion: "Reproduce las letras del alfabeto." },
  { id: 610, descripcion: "Da forma a las letras y las liga para construir palabras." },
  { id: 611, descripcion: "Segmenta palabras y oraciones." },
  { id: 612, descripcion: "Escribe textos siguiendo una secuencia." },
  { id: 613, descripcion: "Produce textos con diferentes propósitos." },
];

// ======================================================
// VIII — MATEMÁTICAS
// ======================================================
const ITEMS_MATEMATICAS = [
  { id: 801, descripcion: "Ordena objetos de menor a mayor y viceversa." },
  { id: 802, descripcion: "Agrupa y clasifica objetos." },
  { id: 803, descripcion: "Asocia los símbolos numéricos a una cantidad." },
  { id: 804, descripcion: "Comprende que la posición de un número determina su valor." },
  { id: 805, descripcion: "Lee y escribe números." },
  { id: 806, descripcion: "Realiza la operación que corresponde a partir de signos matemáticos." },
  { id: 807, descripcion: "Realiza cálculos escritos en operaciones matemáticas." },
  { id: 808, descripcion: "Realiza cálculos mentales en operaciones matemáticas." },
  { id: 809, descripcion: "Asocia objetos del entorno a formas geométricas." },
  { id: 810, descripcion: "Ubica posiciones y trayectoria en el espacio considerando una ubicación concreta." },
  { id: 811, descripcion: "Resuelve problemas matemáticos a nivel de su curso." },
];

const SUBSECTORES = {
  parvularia: [
    "Formación personal y social",
    "Comunicación y lenguaje verbal",
    "Relaciones lógico matemáticas",
    "Relación con el medio social",
    "Relación con el medio natural",
    "Comunicación: Lenguaje artístico",
  ],
  basica: [
    "Lenguaje y comunicación",
    "Lengua extranjera",
    "Educación matemática",
    "Comprensión del medio social",
    "Comprensión del medio natural",
    "Educación artística",
    "Educación física",
    "Educación tecnológica",
  ],
  media: [
    "Filosofía y Psicología",
    "Lenguaje y Comunicación",
    "Idioma Extranjero",
    "Matemática",
    "Historia, Geografía y Ciencias Sociales",
    "Biología",
    "Física",
    "Química",
    "Artes Visuales o Artes Musicales",
    "Educación Física",
    "Educación Tecnológica",
    "Religión",
  ],
  adultos: [
    "Lenguaje y comunicación",
    "Matemáticas",
    "Estudios sociales",
    "Ciencias naturales",
    "Formación en oficios",
    "Formación instrumental",
    "Formación diferenciada",
  ],
};
// ESTADO PARA ESTRATEGIAS DE APOYO
const ESTRATEGIAS_LISTA = [
  "Materiales y recursos alternativos para favorecer la comprensión",
  "Atención individualizada en momentos específicos",
  "Utilización de medios y recursos audiovisuales",
  "Guías de estudio adicionales",
  "Esquemas con síntesis de conceptos",
  "Esquemas de síntesis por unidades de estudio",
  "Material complementario (textos, láminas, juegos)",
  "Ubicación del estudiante en un lugar estratégico",
  "Tiempo adicional para actividades o tareas",
  "Graduación de exigencias acorde al nivel",
  "Adecuación de procedimientos de evaluación",
  "Aprendizaje cooperativo / tutoría entre pares",
  "Evaluaciones para determinar fortalezas y debilidades",
  "Otras (describa)"
];



function EvaluacionPsicoForm({ evaluacion, onSuccess }) {
  // Datos base
  const [formData, setFormData] = useState({
    estudiante: "",
    fecha: "",
    evaluador: "",
  });

  // Curso → Alumno
  const [cursoId, setCursoId] = useState("");
  const [cursos, setCursos] = useState([]);
  const [alumnos, setAlumnos] = useState([]);
  const [alumno, setAlumno] = useState(null);

  // IDENTIFICACIÓN / TRAYECTORIA / SITUACIÓN
  const [identificacion, setIdentificacion] = useState({
    observaciones_identificacion: "",
  });

  const [trayectoria, setTrayectoria] = useState({
    observaciones_trayectoria: "",
  });

  const [situacion, setSituacion] = useState({
    aspectos_destacados: "",
    observaciones_situacion: "",
  });

  // SUBDIMENSIÓN I
  const [valoresItems, setValoresItems] = useState(
    ITEMS_COMUNICATIVAS.reduce((acc, item) => ({ ...acc, [item.id]: 0 }), {})
  );

  const [fortalezaArea, setFortalezaArea] = useState("");
  const [debilidadArea, setDebilidadArea] = useState("");
  const [sintesisArea, setSintesisArea] = useState("");
