          onChange={() => handleSubsector(sub, "destacado")}
        />{" "}
        ✔ Destacado
      </label>

      <label>
        <input
          type="checkbox"
          checked={subsectoresSeleccionados[sub] === "dificultad"}
          onChange={() => handleSubsector(sub, "dificultad")}
        />{" "}
        ✘ Dificultad
      </label>
    </div>
  ))}

  {/* EDUCACIÓN DE ADULTOS */}
  <h5 className="mt-4 text-primary">Educación de Adultos</h5>
  {SUBSECTORES.adultos.map((sub) => (
    <div key={sub} className="d-flex align-items-center mb-2">
      <span className="me-3" style={{ width: "280px" }}>{sub}</span>

      <label className="me-3">
        <input
          type="checkbox"
          checked={subsectoresSeleccionados[sub] === "destacado"}
          onChange={() => handleSubsector(sub, "destacado")}
        />{" "}
        ✔ Destacado
      </label>

      <label>
        <input
          type="checkbox"
          checked={subsectoresSeleccionados[sub] === "dificultad"}
          onChange={() => handleSubsector(sub, "dificultad")}
        />{" "}
        ✘ Dificultad
      </label>
    </div>
  ))}
</div>
{/* ====================================================== */}
{/* IX — OTRAS ESTRATEGIAS DE APOYO UTILIZADAS (TABLA)    */}
{/* ====================================================== */}

<h4 className="mt-4">IX. Otras estrategias de apoyo utilizadas por el profesional PIE</h4>

<table className="table table-bordered align-middle mt-3">
  <thead className="table-secondary text-center">
    <tr>
      <th style={{ width: "50%" }}>Describa la estrategia utilizada</th>
      <th style={{ width: "25%" }}>Aplicada</th>
      <th style={{ width: "25%" }}>Exitosa</th>
    </tr>
  </thead>

  <tbody>
    {/* FILA 1 */}
    <tr>
      <td>
        <input
          type="text"
          className="form-control"
          placeholder="Estrategia aplicada..."
          value={estrategias[0].descripcion}
          onChange={(e) => handleEstrategiaChange(0, "descripcion", e.target.value)}
        />
      </td>
      <td className="text-center">
        <input
          type="checkbox"
          checked={estrategias[0].aplicada}
          onChange={(e) => handleEstrategiaChange(0, "aplicada", e.target.checked)}
        />
      </td>
      <td className="text-center">
        <input
          type="checkbox"
          checked={estrategias[0].exitosa}
          onChange={(e) => handleEstrategiaChange(0, "exitosa", e.target.checked)}
        />
      </td>
    </tr>

    {/* FILA 2 */}
    <tr>
      <td>
        <input
          type="text"
          className="form-control"
          placeholder="Estrategia aplicada..."
          value={estrategias[1].descripcion}
          onChange={(e) => handleEstrategiaChange(1, "descripcion", e.target.value)}
        />
      </td>
      <td className="text-center">
        <input
          type="checkbox"
          checked={estrategias[1].aplicada}
          onChange={(e) => handleEstrategiaChange(1, "aplicada", e.target.checked)}
        />
      </td>
      <td className="text-center">
        <input
          type="checkbox"
          checked={estrategias[1].exitosa}
          onChange={(e) => handleEstrategiaChange(1, "exitosa", e.target.checked)}
        />
      </td>
    </tr>

    {/* FILA 3 */}
    <tr>
      <td>
        <input
          type="text"
          className="form-control"
          placeholder="Estrategia aplicada..."
          value={estrategias[2].descripcion}
          onChange={(e) => handleEstrategiaChange(2, "descripcion", e.target.value)}
        />
      </td>
      <td className="text-center">
        <input
          type="checkbox"
          checked={estrategias[2].aplicada}
          onChange={(e) => handleEstrategiaChange(2, "aplicada", e.target.checked)}
        />
      </td>
      <td className="text-center">
        <input
          type="checkbox"
          checked={estrategias[2].exitosa}
          onChange={(e) => handleEstrategiaChange(2, "exitosa", e.target.checked)}
        />
      </td>
    </tr>
  </tbody>
</table>


{/* ====================================================== */}
{/* X — OTRAS ESTRATEGIAS UTILIZADAS (Texto libre)         */}
{/* ====================================================== */}

<h5 className="mt-4">Otras estrategias utilizadas</h5>

<textarea
  className="form-control"
  rows="3"
  placeholder="Escriba aquí otras estrategias utilizadas por el profesional..."
  value={otrasEstrategias}
  onChange={(e) => setOtrasEstrategias(e.target.value)}
/>

    



      <button type="submit" className="btn btn-success w-100 mt-3">
        {evaluacion ? "Actualizar evaluación" : "Crear evaluación"}
      </button>
    </form>
  );
}

export default EvaluacionPsicoForm;
